var map_BGPVIPConfigSpec = map[string]string{
	"":              "BGPVIPConfigSpec describes the BGP peering used to advertise the API and Ingress VIPs.",
	"localASN":      "localASN is the BGP autonomous system number (ASN) the cluster's BGP speakers present to the configured peers. Use the ASN your network administrator assigned to the cluster - the peer routers must expect it or no session establishes; private-range ASNs (e.g. 64512-65534) are typical for datacenter fabrics. Must be at least 1 and must not exceed 4294967295.",
	"defaultPeers":  "defaultPeers are the BGP peers every node establishes sessions with, unless the node is named in hostOverrides. Must have at least 1 entry and must not exceed 16 entries, unique by peerAddress.",
	"communities":   "communities are BGP community strings attached to the VIP advertisements: \"n:n\" classic communities (RFC 1997) where each segment is a 16-bit value of at least 0 and not exceeding 65535, or \"n:n:n\" large communities (RFC 8092) where each segment is a 32-bit value of at least 0 and not exceeding 4294967295. When omitted, no communities are attached. Entries are unique; when set, must have at least 1 entry and must not exceed 8 entries.",
	"hostOverrides": "hostOverrides replaces (does not merge with) defaultPeers for the named nodes. Only the per-node peer file rendered by the machine-config-operator consumes overrides; the cluster-wide session configuration rendered by the cluster-network-operator uses defaultPeers. When omitted, all nodes use defaultPeers; when set, must have at least 1 entry and must not exceed 256 entries, unique by hostname.",
}

func (BGPVIPConfigSpec) SwaggerDoc() map[string]string {
	return map_BGPVIPConfigSpec
}

