var map_BGPVIPPeer = map[string]string{
	"":                     "BGPVIPPeer describes one BGP peer.",
	"peerAddress":          "peerAddress is the IP address of the BGP peer (IPv4 or IPv6) in canonical form (lowercase, no leading zeros, IPv6 zero-compressed); must be at least 2 characters in length and must not exceed 45 characters. The session's address family follows the address family of this value. Canonical form is required so that two spellings of one address cannot form duplicate peers.",
	"peerASN":              "peerASN is the autonomous system number of the peer. Must be at least 1 and must not exceed 4294967295.",
	"passwordSecret":       "passwordSecret references the Secret carrying the TCP MD5 password (RFC 2385) for the session. The Secret must be of type kubernetes.io/basic-auth, live in the openshift-config namespace, and carry the password in its \"password\" key (at most 80 bytes, the kernel's TCP MD5 limit). The Secret type, key, and size requirements are not validated by the API server; the consumers validate them when resolving the reference and must never surface the Secret contents in status, events, or logs. Passwords are never stored in this API. When omitted, the session is unauthenticated.",
	"port":                 "port is the TCP port of the BGP session; must be at least 1 and must not exceed 65535. When omitted, port 179 is used.",
	"failureDetection":     "failureDetection determines how a failed peer is detected. When set to \"BFD\", a BFD session is established with the peer and BGP reacts to BFD failure detection. When set to \"HoldTimer\", failure detection relies on the BGP hold timer alone. When omitted, failure detection relies on the BGP hold timer.",
	"peerReachability":     "peerReachability describes how the peer is reached. When set to \"MultiHop\", the session may be established with a peer several router hops away. When set to \"DirectlyConnected\", the peer must be on a directly connected network. When omitted, the peer must be directly connected.",
	"holdTimeSeconds":      "holdTimeSeconds is the BGP hold time in seconds; must be at least 3 (the RFC 4271 minimum for a non-zero hold time) and must not exceed 65535. When omitted, no hold time is configured and the FRR default (180 seconds) applies. When both holdTimeSeconds and keepaliveTimeSeconds are set, holdTimeSeconds must be at least 3 times keepaliveTimeSeconds.",
	"keepaliveTimeSeconds": "keepaliveTimeSeconds is the BGP keepalive interval in seconds; must be at least 1 and must not exceed 65535. When omitted, no keepalive interval is configured and the FRR default (60 seconds) applies. When both holdTimeSeconds and keepaliveTimeSeconds are set, holdTimeSeconds must be at least 3 times keepaliveTimeSeconds.",
}

func (BGPVIPPeer) SwaggerDoc() map[string]string {
	return map_BGPVIPPeer
}

